findings.codeql_raw_query:
/**
 * @name Potential SSRF via yarl URL usage
 * @description Detect flows from remote input into yarl.URL construction without validation
 * @kind path-problem
 * @problem.severity warning
 * @id py/yarl/ssrf-url-construction
 * @tags security
 *       external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module YarlUrlConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("yarl").getMember(["URL", "URL.build"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module YarlUrlFlow = TaintTracking::Global<YarlUrlConfig>;
import YarlUrlFlow::PathGraph

from YarlUrlFlow::PathNode source, YarlUrlFlow::PathNode sink
where YarlUrlFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data flows into yarl.URL construction, which may lead to SSRF if used for HTTP requests.", source, "user input"
